function text(v) {
  return String(v ?? '').trim();
}
function digits(v) {
  return String(v ?? '').replace(/\D/g, '');
}
function num(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(String(v ?? '').replace(/[^\d.]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function newest(rows, keys) {
  return rows.slice().sort((a, b) => {
    const ta = Date.parse(a[keys[0]] || a[keys[1]] || 0) || 0;
    const tb = Date.parse(b[keys[0]] || b[keys[1]] || 0) || 0;
    return tb - ta;
  })[0];
}
function fromEmail(raw) {
  if (raw && typeof raw === 'object') {
    return fromEmail(raw.value?.[0]?.address || raw.address || raw.text || '');
  }
  const s = text(raw);
  const m = s.match(/<([^>]+@[^>]+)>/) || s.match(/([^\s<>]+@[^\s<>]+)/);
  return (m ? m[1] : s).toLowerCase();
}

const mail = $('Gmail Trigger').first().json;
const subject = text(mail.subject || mail.Subject);
const sender = fromEmail(mail.from || mail.From || mail.headers?.from || '');

if (/proforma invoice/i.test(subject) && !/^\s*re\s*:/i.test(subject)) return [];
if (!sender.includes('@')) return [];

const buyers = $('Get Buyers').all().map((i) => i.json);
const buyer = buyers.find((b) => text(b.Email).toLowerCase() === sender);
if (!buyer) return [];

const phone = digits(buyer['Phone/WhatsApp']);
const buyerId = text(buyer['Buyer ID']);
const requests = $('Get Buyer Requests').all().map((i) => i.json);
const eligible = requests.filter((r) => {
  const st = text(r.Status).toLowerCase();
  if (st !== 'firm interest') return false;
  const rid = text(r['Buyer ID']);
  return rid === buyerId || (phone && digits(rid) === phone) || text(r.Email).toLowerCase() === sender;
});
const req = newest(eligible, ['Last Updated', 'Date Received']);
if (!req) return [];

const buyerPrice = num(req['Target Price']);
if (buyerPrice <= 0) throw new Error('Target Price missing on ' + req['Request ID']);

const refDigits = text(req['Request ID']).replace(/\D/g, '');
return [{
  json: {
    document: 'proforma',
    product: text(req['Product Name']),
    quantity_mt: num(req['Quantity (MT)']),
    buyer_unit_price: buyerPrice,
    currency: text(req.Currency) || 'USD',
    incoterm: text(req.Incoterm),
    price_basis: text(req['Destination Port']),
    load_port: '',
    discharge_port: text(req['Destination Port']),
    packing: text(req.Packing),
    shipping: text(req['Delivery/Shipment Window']),
    payment_terms: text(req['Payment Terms']),
    reference: text(req['Request ID']),
    order_ref: refDigits ? ('AQ' + refDigits.padStart(6, '0')) : 'AQ000000',
    buyer: {
      name: text(req['Buyer Contact'] || buyer['Contact Name']),
      email: text(buyer.Email),
      phone: buyer['Phone/WhatsApp'] || '',
    },
  },
}];

const deal = $('Match firm-interest buyer').first().json;
const file = $('Convert to File').first();
const binKey = file?.binary ? Object.keys(file.binary)[0] : null;
const pdf = binKey ? file.binary[binKey] : null;
if (!pdf) throw new Error('Missing PI PDF binary');
if (!String(deal.buyer?.email || '').includes('@')) throw new Error('Buyer Email missing');

return [{
  json: {
    to: deal.buyer.email,
    name: deal.buyer.name,
    product: deal.product,
    qty: deal.quantity_mt,
    price: deal.buyer_unit_price,
    incoterm: deal.incoterm,
    reference: deal.reference,
  },
  binary: { data: pdf },
}];
